import{z as T,x as l,o as r,c as i,q as t,j as A,D as n,d as e,s as o,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"RCT 的设计与分析","description":"","frontmatter":{"title":"RCT 的设计与分析","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pe-rct-design-analysis.md","filePath":"econ/pe-rct-design-analysis.md","lastUpdated":1791063341000}'),d={name:"econ/pe-rct-design-analysis.md"};function D(p,E,C,m,c,h){const B=l("Mermaid");return r(),i("div",null,[E[2]||(E[2]=t('<h1 id="rct-的设计与分析" tabindex="-1">RCT 的设计与分析 <a class="header-anchor" href="#rct-的设计与分析" aria-label="Permalink to &quot;RCT 的设计与分析&quot;">​</a></h1><div class="epigraph"><p>随机化买到的只是期望意义上的可比；设计上偷的懒，不会消失，会在方差、流失与名义水平里逐行还回来。</p><footer>—— 据 Duflo, Glennerster and Kremer 2007；Bruhn and McKenzie, Journal of Economic Surveys 2009；Athey and Imbens 2017 整理</footer></div><p><a href="/econ/pe-iv-heterogeneous-compliers">上一课</a>把 IV 的对象钉在依从者边际上——不依从本身就是一个设计问题。本课从源头处理依从：随机化实验。<a href="/econ/experimental-methods">实验经济学方法</a>给了诱导价值与内外部有效的分界，<a href="/econ/potential-outcomes">潜在结果</a>给了随机化的合法性；本课写设计与分析的工程细节：分组单位、分层、功效预算，ITT 与 TOT 的分工，以及「按设计分析」这条纪律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机化保证的是分配机制与潜结果独立，于是两组在期望上可比；设计错误都不在「可比」上显形，而在别处。<strong>分组单位</strong>：政策有溢出（疫苗、信息、价格）时个体随机化把对照污染成部分处理，要按簇随机——而簇内的相关性立刻吃掉有效样本。<strong>分层</strong>：不做分层的纯随机在中小样本里会留下基线不平衡的坏抽签，事后加协变量救不回设计丢掉的那部分。<strong>功效</strong>：样本量若不按设计效应预算，试验结束时置信区间宽到回答不了政策问题——钱已花完。<strong>流失</strong>：中途退出若与处理相关，连 ITT 都不干净，因为留在样本里的两组不再是随机的两组。<strong>多结局</strong>：二十个结局指标各用名义 5%，主结论的名义水平早已坏掉，那是<a href="/econ/multiple-testing-econ">多重检验</a>的现成口径。</p><p><span class="marginnote">设计效应 \\(1+(m-1)\\rho\\) 的账要会算：簇均 \\(m=40\\)、组内相关 \\(\\rho=0.1\\) 时，有效样本缩到约五分之一——同样的钱，MDE 差一倍不止。簇随机不做这笔预算，是功效虚高的最常见来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计三步。第一，定随机化单位：有溢出或行政单位约束就用簇，接受功效损失。第二，分层：分层变量用基线结局或其预测指数（利润指数），层数有限、每层够大；配对随机化是极端分层（Bruhn–McKenzie 的综述口径）。<span class="marginnote">直觉类比：分层随机像「先分堆、再抛硬币」——按基线把人先分成几摞，再在每一摞内部各抛一次硬币。这样每摞里两组人数天然均衡，基线比较不靠运气；不分层的纯随机在中小样本里可能整摞落进同一组，事后加协变量救不回这份损失。</span>第三，预注册主结局与主规格，把 \\(m\\) 压回 1。分析按设计走：随机化用到的分层必须以分层固定效应进回归，否则精度白丢；ITT 为主——抽中与实际接受分开报；不依从时 TOT 用随机分配当工具，估计对象正是上一课的依从者 LATE，这里只换语境；差异流失要报两组流失率与流失者的基线差，并给界；簇随机配簇级聚类或随机化推断（<a href="/econ/clustered-se">聚类标准误</a>的口径），设计形态允许时随机化推断是最贴设计的检验。</p>',8)),(r(),A(s,null,{default:n(()=>[o(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNIT%7B%22%E6%9C%89%E6%BA%A2%E5%87%BA%E6%88%96%E8%A1%8C%E6%94%BF%E7%BA%A6%E6%9D%9F%3F%22%7D%20--%3E%7C%E6%98%AF%7C%20CLUS%5B%22%E7%B0%87%E9%9A%8F%E6%9C%BA%E5%8C%96%E5%B9%B6%E9%A2%84%E7%AE%97%E8%AE%BE%E8%AE%A1%E6%95%88%E5%BA%94%22%5D%0A%20%20UNIT%20--%3E%7C%E5%90%A6%7C%20IND%5B%22%E4%B8%AA%E4%BD%93%E9%9A%8F%E6%9C%BA%E5%8C%96%22%5D%0A%20%20IND%20--%3E%20STR%5B%22%E5%88%86%E5%B1%82%3A%20%E5%9F%BA%E7%BA%BF%E7%BB%93%E5%B1%80%E6%88%96%E6%8C%87%E6%95%B0%22%5D%0A%20%20CLUS%20--%3E%20STR%0A%20%20STR%20--%3E%20REG%5B%22%E5%88%86%E5%B1%82%E5%9B%BA%E5%AE%9A%E6%95%88%E5%BA%94%E8%BF%9B%E5%9B%9E%E5%BD%92%22%5D%0A%20%20REG%20--%3E%20ITT%5B%22ITT%20%E4%B8%BA%E4%B8%BB%22%5D%0A%20%20ITT%20--%3E%20NC%7B%22%E6%9C%89%E4%BE%9D%E4%BB%8E%E9%97%AE%E9%A2%98%3F%22%7D%0A%20%20NC%20--%3E%7C%E6%98%AF%7C%20TOT%5B%22TOT%3A%20%E5%88%86%E9%85%8D%E5%BD%93%E5%B7%A5%E5%85%B7%22%5D%0A%20%20NC%20--%3E%7C%E5%90%A6%7C%20OUT%5B%22%E5%A4%9A%E7%BB%93%E5%B1%80%3A%20%E4%B8%BB%E7%BB%93%E5%B1%80%E9%A2%84%E6%B3%A8%E5%86%8C%22%5D%0A%20%20TOT%20--%3E%20OUT%0A%20%20OUT%20--%3E%20ATTR%5B%22%E6%B5%81%E5%A4%B1%E6%8A%A5%E5%91%8A%E4%B8%8E%E7%95%8C%22%5D%0A"})]),fallback:n(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("机制核心是"),a("strong",null,"按设计分析"),e("：合法的推断单位是随机化发生的那一层。"),a("span",{class:"marginnote"},"术语翻译：ITT（intention-to-treat）是「分到就算」的口径——按抽签结果分组比较，不管实际接不接受处理；TOT 是「真的接受了处理的人」身上的效应。ITT 常因不依从被稀释变小，但政策推广时面对的正是「有人不遵从」的现实，所以 ITT 是决策该用的口径，TOT 只回答「药对依从者有多灵」。"),e("分层信息不进回归，设计给的精度被扔掉；簇被当个体，名义标准误比真的小好几倍；看过数据再挑主结局，随机化保证的 \\(\\alpha\\) 作废。这些都不是哲学立场，是设计契约的条款——随机化用一份分配机制换了可比性，分析的每一行都在决定这份契约是否被履行。")],-1)),E[5]||(E[5]=a("p",null,"不这么做会错在哪：不做设计效应预算，试验功效虚高近五倍；不做流失分析，把「差异流失后的样本」当随机样本解释；ITT 与 TOT 不分开，读者拿依从者效应当全员效应用。",-1)),(r(),A(s,null,{default:n(()=>[o(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E9%9A%8F%E6%9C%BA%E5%88%86%E9%85%8D%3A%20%E6%8A%BD%E4%B8%AD%20%2F%20%E6%B2%A1%E6%8A%BD%E4%B8%AD%22%5D%20--%3E%20ITT%5B%22ITT%3A%20%E6%8C%89%E5%88%86%E9%85%8D%E6%AF%94%E8%BE%83%2C%20%E8%A6%86%E7%9B%96%E5%85%A8%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20R%20--%3E%20C%7B%22%E5%AE%9E%E9%99%85%E6%8E%A5%E5%8F%97%E5%A4%84%E7%90%86%3F%22%7D%0A%20%20C%20--%20%22%E4%BE%9D%E4%BB%8E%E8%80%85%22%20--%3E%20TOT%5B%22TOT%3A%20%E5%88%86%E9%85%8D%E5%BD%93%E5%B7%A5%E5%85%B7%2C%20%E5%8F%AA%E8%A6%86%E7%9B%96%E4%BE%9D%E4%BB%8E%E8%80%85%22%5D%0A%20%20C%20--%20%22always%20%2F%20never-takers%22%20--%3E%20NO%5B%22%E5%AF%B9%E5%88%86%E9%85%8D%E6%97%A0%E5%8F%8D%E5%BA%94%2C%20%E4%B8%8D%E8%BF%9B%20TOT%22%5D%0A%20%20ITT%20--%3E%20DIF%7B%22%E4%B8%AD%E9%80%94%E9%80%80%E5%87%BA%E4%B8%8E%E5%88%86%E9%85%8D%E7%9B%B8%E5%85%B3%3F%22%7D%0A%20%20DIF%20--%20%22%E6%98%AF%22%20--%3E%20BROKEN%5B%22%E7%95%99%E5%9C%A8%E6%A0%B7%E6%9C%AC%E7%9A%84%E4%B8%A4%E7%BB%84%E4%B8%8D%E5%86%8D%E9%9A%8F%E6%9C%BA%2C%20ITT%20%E4%B9%9F%E8%A2%AB%E6%AF%81%22%5D%0A"})]),fallback:n(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p>上图回答的问题是「ITT 与 TOT 各自量的是谁、何时失效」：方法图给出设计选择的流程，这张画出分配到接受之间的第二道门——不依从把 TOT 缩到依从者，差异流失连 ITT 的可比性都拆掉；推断的合法性逐级取决于哪一层的随机化还完好。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做伦理审查与知情同意的制度清单，也不把 RCT 写成评估的唯一金标准：内外部有效的分界沿<a href="/econ/experimental-methods">实验经济学方法</a>，外部有效性是本课程后两课的正题。序贯试验与可选停止的推断不展开。RCT 与准实验的关系要摆正：它不是「更高级的 DiD」，是另一种识别契约——假设更少、可搬性更弱，两种契约的纪律一样硬。</p><p>后课默认：实验报告按设计条款读；估计量如何变成决策，下一课换目标函数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机化单位跟着溢出与行政约束走；簇随机必须预算 \\(1+(m-1)\\rho\\)。</li><li>分层变量用基线结局或预测指数，层数有限；分层进回归。</li><li>ITT 为主；TOT 用分配当工具，对象是依从者 LATE。</li><li>差异流失毁掉 ITT，报流失率、基线差与界。</li><li>主结局预注册；多结局的校正沿多重检验口径。</li><li>出处：Duflo, Glennerster and Kremer 2007；Bruhn and McKenzie 2009；Athey and Imbens 2017；Imbens and Rubin 2015。</li></ul>',6))])}const f=T(d,[["render",D]]);export{I as __pageData,f as default};
